import java.util.HashMap;

public class Main {
    public static void main(String[] args) {
        // Key-Value Pair Storage
        HashMap<String, Integer> map = new HashMap<>();

        // 1. put(key, value)
        // Hash("Apple") -> Index 3 -> Store Node
        map.put("Apple", 1000);

        // 2. Collision Handling
        // Hash("Banana") -> Index 3 -> Collision! -> Link Next
        // (Assume collision happens for demo)
        map.put("Banana", 2000);

        // 3. get(key)
        // Hash("Apple") -> Index 3 -> Search Linked List -> Found
        System.out.println("Price: " + map.get("Apple"));
    }
}
